window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9e9254af07897bc0"]={"versions": [{"id": "FIG-9e9254af07897bc0", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Bitfeld-Spezifikation (Protokoll-/Frame-Layout) im Kontext des AUTOSAR-Debugging-Moduls (Dbg). Das Diagramm definiert die Belegung und Semantik des Bitfelds „Communication Control Bits“ innerhalb der Transport- bzw. Kommunikationsrahmen zur Steuerung segmentierter Debug-Datenübertragungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Bitfeld umfasst 4 Bits (Bitpositionen 0 bis 3):</p>\n<ul class=\"fig-list\"><li>Bit 0 (<code>TP1st</code>): Kennzeichnung des ersten Übertragungsrahmens bei segmentierter Datenübertragung („Bit that marks the first frame of a segmented data transmisson“). Wertebereich: <code>0</code> = nachfolgender Rahmen (consecutive frame), <code>1</code> = erster Rahmen (first frame).\n</li><li>Bits 1..3 (<code>reserved</code>): Reservierter Bereich („Currently not used“), ohne zugewiesene Wertesemantik.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Bei Beginn einer segmentierten Datenübertragung setzt der Sender im Steuerbitfeld das Bit 0 (<code>TP1st</code>) auf <code>1</code>, um den ersten Rahmen (First Frame) zu signalisieren. Alle nachfolgenden Übertragungsrahmen derselben Sequenz tragen für Bit 0 den Wert <code>0</code> (Consecutive Frame). Die Bits 1 bis 3 verbleiben während der gesamten Sequenz ungenutzt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Sender und Empfänger des Debug-Kommunikationsprotokolls: Bit 0 muss zur Rahmenunterscheidung bei Segmentierung strikt nach der binären Codierung (0 bzw. 1) ausgewertet und gesetzt werden. Die reservierten Bits 1..3 dürfen für die Ablaufsteuerung nicht herangezogen werden und sind standardmäßig als unbenutzt zu behandeln.</p>"}, {"id": "FIG-3b78b80dba0384d1", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Bitfeld-Spezifikation (Protokoll-/Frame-Layout) im Kontext des AUTOSAR-Debugging-Moduls (Dbg). Das Diagramm definiert die Belegung und Semantik des Bitfelds „Communication Control Bits“ innerhalb der Transport- bzw. Kommunikationsrahmen zur Steuerung segmentierter Debug-Datenübertragungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Bitfeld umfasst 4 Bits (Bitpositionen 0 bis 3):</p>\n<ul class=\"fig-list\"><li>Bit 0 (<code>TP1st</code>): Kennzeichnung des ersten Übertragungsrahmens bei segmentierter Datenübertragung („Bit that marks the first frame of a segmented data transmisson“). Wertebereich: <code>0</code> = nachfolgender Rahmen (consecutive frame), <code>1</code> = erster Rahmen (first frame).\n</li><li>Bits 1..3 (<code>reserved</code>): Reservierter Bereich („Currently not used“), ohne zugewiesene Wertesemantik.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Bei Beginn einer segmentierten Datenübertragung setzt der Sender im Steuerbitfeld das Bit 0 (<code>TP1st</code>) auf <code>1</code>, um den ersten Rahmen (First Frame) zu signalisieren. Alle nachfolgenden Übertragungsrahmen derselben Sequenz tragen für Bit 0 den Wert <code>0</code> (Consecutive Frame). Die Bits 1 bis 3 verbleiben während der gesamten Sequenz ungenutzt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Sender und Empfänger des Debug-Kommunikationsprotokolls: Bit 0 muss zur Rahmenunterscheidung bei Segmentierung strikt nach der binären Codierung (0 bzw. 1) ausgewertet und gesetzt werden. Die reservierten Bits 1..3 dürfen für die Ablaufsteuerung nicht herangezogen werden und sind standardmäßig als unbenutzt zu behandeln.</p>"}, {"id": "FIG-2dd537116d9061e5", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Bitfeld-Spezifikation (Protokoll-/Frame-Layout) im Kontext des AUTOSAR-Debugging-Moduls (Dbg). Das Diagramm definiert die Belegung und Semantik des Bitfelds „Communication Control Bits“ innerhalb der Transport- bzw. Kommunikationsrahmen zur Steuerung segmentierter Debug-Datenübertragungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Bitfeld umfasst 4 Bits (Bitpositionen 0 bis 3):</p>\n<ul class=\"fig-list\"><li>Bit 0 (<code>TP1st</code>): Kennzeichnung des ersten Übertragungsrahmens bei segmentierter Datenübertragung („Bit that marks the first frame of a segmented data transmisson“). Wertebereich: <code>0</code> = nachfolgender Rahmen (consecutive frame), <code>1</code> = erster Rahmen (first frame).\n</li><li>Bits 1..3 (<code>reserved</code>): Reservierter Bereich („Currently not used“), ohne zugewiesene Wertesemantik.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Bei Beginn einer segmentierten Datenübertragung setzt der Sender im Steuerbitfeld das Bit 0 (<code>TP1st</code>) auf <code>1</code>, um den ersten Rahmen (First Frame) zu signalisieren. Alle nachfolgenden Übertragungsrahmen derselben Sequenz tragen für Bit 0 den Wert <code>0</code> (Consecutive Frame). Die Bits 1 bis 3 verbleiben während der gesamten Sequenz ungenutzt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Sender und Empfänger des Debug-Kommunikationsprotokolls: Bit 0 muss zur Rahmenunterscheidung bei Segmentierung strikt nach der binären Codierung (0 bzw. 1) ausgewertet und gesetzt werden. Die reservierten Bits 1..3 dürfen für die Ablaufsteuerung nicht herangezogen werden und sind standardmäßig als unbenutzt zu behandeln.</p>"}], "trans": [{"from": "FIG-9e9254af07897bc0", "to": "FIG-3b78b80dba0384d1", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-3b78b80dba0384d1", "to": "FIG-2dd537116d9061e5", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
